(async () => {
  const owner = 'DoshideDK';
  const repo = 'JS-Slash-Runner';
  const branch = 'main';
  const path = encodeURIComponent('世界书管理器.js');
  const cdn = 'https://cdn.jsdelivr.net/gh';
  let url = `${cdn}/${owner}/${repo}@${branch}/${path}`;

  try {
    const res = await fetch(`https://api.github.com/repos/${owner}/${repo}/commits/${branch}`, {
      cache: 'no-store',
      headers: { Accept: 'application/vnd.github+json' },
    });
    if (res.ok) {
      const sha = (await res.json())?.sha;
      if (sha) url = `${cdn}/${owner}/${repo}@${sha}/${path}`;
    }
  } catch (error) {
    console.warn('[世界书管理器] 获取最新提交失败，回退到分支地址', error);
  }

  await import(url);
})();
